// 32x polyphase interpolation of the OKI output (board-side; jt6295 is untouched).
// Kernels (steel_audio_fir_rom, generated by scripts/gen_audio_fir.py):
//   bank 0 Enhanced: 32-tap Kaiser windowed sinc, flat to 3.3 kHz (no droop in the 2.5-3.8 kHz top
//          octave of the OKI band), images >= 50 dB down from 4.3 kHz; steel_audio_exciter adds treble.
//   bank 1 MAME: MAME 0.289's default (LOFI) 4-point polynomial resampler, no anti-image filter.
// Output is at 32x the OKI rate (~242 kHz). Each phase has unity DC gain, so held input passes unchanged.
// Phase spacing is the measured OKI sample period / 32, so both profiles' OKI clocks work.
module steel_audio_upsample(
    input wire clk,reset,
    input wire sample,                  // jt6295 sample strobe; new pcm is valid the next clock
    input wire signed [13:0] pcm,
    input wire bank,                    // 0 Enhanced, 1 MAME LOFI
    output reg signed [15:0] out,
    output reg out_valid                // one clock when out updates (32x the OKI rate)
);
    localparam integer TAPS=32;
    reg signed [13:0] history[0:TAPS-1];
    reg sample_q=0;
    reg [15:0] period=16'd6019,since=0,next_tick=0;
    reg [4:0] phase=0;
    reg ticks_done=1;
    // MAC engine
    reg busy=0;
    reg [5:0] tap=0;
    reg [4:0] mac_phase=0;
    reg [10:0] rom_addr=0;
    wire signed [17:0] coef;
    reg signed [13:0] x_q=0;
    reg signed [31:0] product=0;
    reg signed [36:0] acc=0;
    reg [1:0] drain=0;
    reg mul_valid=0,mul_valid_q=0,add_valid=0;
    reg signed [13:0] x_q_d=0;           // x_q lines up with the ROM's registered output
    steel_audio_fir_rom rom(.clk(clk),.addr(rom_addr),.data(coef));
    integer i;
    initial for(i=0;i<TAPS;i=i+1)history[i]=14'sd0;
    wire signed [36:0] rounded=acc+37'sd32768;       // Q16 coefficients: round half up before >>16
    wire signed [20:0] scaled=rounded[36:16];
    always @(posedge clk)begin
        sample_q<=sample;
        if(reset)begin
            since<=0;next_tick<=0;phase<=0;ticks_done<=1;busy<=0;tap<=0;acc<=0;
            mul_valid<=0;mul_valid_q<=0;add_valid<=0;drain<=0;out<=16'sd0;out_valid<=0;period<=16'd6019;
        end else begin
            since<=since+1'b1;
            out_valid<=0;
            // Accept a new OKI sample and restart the 32 output phases.
            if(sample_q)begin
                for(i=TAPS-1;i>0;i=i-1)history[i]<=history[i-1];
                history[0]<=pcm;
                if(since>16'd2000 && since<16'd20000)period<=since;
                since<=16'd1;phase<=0;next_tick<=0;ticks_done<=0;
            end
            // Launch one output phase every period/32 clocks.
            if(!ticks_done && !busy && !sample_q && since>=next_tick)begin
                busy<=1;tap<=0;mac_phase<=phase;acc<=0;drain<=0;
                next_tick<=next_tick+(period>>5);
                if(phase==5'd31)ticks_done<=1;
                phase<=phase+1'b1;
            end
            // Sequential MAC: ROM address -> coefficient (registered) -> product -> accumulate.
            // Stage timing for an issue at clock c: ROM data and x_q_d valid at c+2,
            // product at c+3, accumulated at the end of c+3.
            mul_valid<=0;mul_valid_q<=mul_valid;add_valid<=mul_valid_q;
            if(busy)begin
                if(tap<TAPS)begin
                    rom_addr<={bank,tap[4:0],mac_phase};
                    x_q<=history[tap[4:0]];
                    tap<=tap+1'b1;
                    mul_valid<=1;
                end else if(drain!=2'd3)drain<=drain+1'b1;
            end
            if(add_valid)acc<=acc+product;
            product<=coef*x_q_d;
            if(busy && tap==TAPS && drain==2'd3)begin
                busy<=0;out_valid<=1;
                out<=scaled>21'sd32767 ? 16'sh7fff : scaled<-21'sd32768 ? 16'sh8000 : scaled[15:0];
            end
        end
    end
    always @(posedge clk)x_q_d<=x_q;
endmodule
